def elem(tag, **attrs):
    n = OxmlElement('w:'+tag)
    for k,v in attrs.items(): n.set(qn('w:'+k),str(v))
    return n

def field(p, instruction, cached='1'):
    n = elem('fldSimple', instr=instruction)
    r = elem('r'); t = elem('t'); t.text = cached; r.append(t); n.append(r); p._p.append(n)

def table(doc, rows=5, cols=3):
    t = doc.add_table(rows=rows, cols=cols); t.alignment = WD_TABLE_ALIGNMENT.CENTER
    t.autofit = False
    widths = [1.1,2.8,2.6] if cols==3 else [6.5/cols]*cols
    for row_index,row in enumerate(t.rows):
        for j,cell in enumerate(row.cells):
            cell.width = Inches(widths[j]); cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
            pr = cell._tc.get_or_add_tcPr(); borders=elem('tcBorders')
            for side in ['top','bottom','left','right']:
                borders.append(elem(side,val='single',sz=4,color='D9D9D9'))
            pr.append(borders); margins=elem('tcMar')
            for side in ['top','bottom','left','right']: margins.append(elem(side,w=100,type='dxa'))
            pr.append(margins); pr.append(elem('shd',fill='17365D' if row_index==0 else ('EEF3F8' if row_index%2==0 else 'FFFFFF')))
            cell.text = (['Código','Descripción','Resultado'][j] if cols==3 else f'Campo {j+1}') if row_index==0 else f'{row_index:03d}' if j==0 else f'Elemento {row_index} de la colección' if j==1 else f'{12+row_index} unidades'
            for p in cell.paragraphs:
                p.paragraph_format.space_after = Pt(3)
                if j==0: p.alignment=WD_ALIGN_PARAGRAPH.CENTER
                for r in p.runs:
                    r.font.size=Pt(10); r.bold=row_index==0
                    r.font.color.rgb=RGBColor.from_string('FFFFFF' if row_index==0 else '000000')
    t.rows[0]._tr.get_or_add_trPr().append(elem('tblHeader'))
    return t

def paragraph(doc, text, style=None): return doc.add_paragraph(text,style)

def base(i,title):
    d=Document(); s=d.sections[0]; s.page_width=Inches(8.5); s.page_height=Inches(11)
    s.top_margin=s.bottom_margin=s.left_margin=s.right_margin=Inches(.85)
    s.header_distance=s.footer_distance=Inches(.35)
    for name,size in [('Normal',11),('Title',26),('Subtitle',12),('Heading 1',17),('Heading 2',13),('Heading 3',11)]:
        st=d.styles[name]; st.font.name='Calibri'; st.font.size=Pt(size); st.font.color.rgb=RGBColor(0,0,0)
        st.paragraph_format.space_after=Pt(8); st.paragraph_format.line_spacing=1.12
    d.core_properties.title=title; d.core_properties.author='Laboratorio documental Arles'
    d.core_properties.subject=f'Caso progresivo {i:02d}'; d.core_properties.keywords=TOPICS[i-1][1]
    d.add_paragraph(title,'Title')
    d.add_paragraph(f'Colección de lectura y edición   Caso {i:02d}','Subtitle')
    # A separate, editable illustration in every fixture, including the simple cases.
    art=d.add_picture(str(ASSETS/f'tema-{i:02d}.png'),width=Inches(1.8 if i==27 else 3 if i==26 else 6.2))
    art._inline.docPr.set('descr',f'Ilustración original del caso {i:02d}: {title}')
    if i==1:
        paragraph(d,'Solicitamos reservar una sala para el club de lectura del barrio. Nos reuniremos el sábado para compartir cuentos, organizar los libros recibidos y preparar el siguiente encuentro.')
    else:
        paragraph(d,INTRO.get(i,f'Este documento desarrolla {title.lower()}. Reúne una explicación, ejemplos y una propuesta de trabajo para que el lector pueda comparar alternativas y tomar una decisión.'))
    paragraph(d,f'Nota editorial del caso {i:02d}: la propuesta está lista para revisión.')
    return d

