def math_expr(d,matrix=False):
    w=NS['w'];m='http://schemas.openxmlformats.org/officeDocument/2006/math'
    content='<m:f><m:num><m:r><m:t>1</m:t></m:r></m:num><m:den><m:r><m:t>f</m:t></m:r></m:den></m:f>'
    if matrix:
        content='<m:m><m:mr><m:e><m:r><m:t>1</m:t></m:r></m:e><m:e><m:r><m:t>2</m:t></m:r></m:e></m:mr><m:mr><m:e><m:r><m:t>3</m:t></m:r></m:e><m:e><m:r><m:t>4</m:t></m:r></m:e></m:mr></m:m><m:r><m:t> + </m:t></m:r><m:rad><m:deg/><m:e><m:r><m:t>x</m:t></m:r></m:e></m:rad>'
    p=d.add_paragraph();p._p.append(parse_xml(f'<m:oMath xmlns:m="{m}">{content}</m:oMath>'))
    p=d.add_paragraph('Relación de energía ');p._p.append(parse_xml(f'<m:oMath xmlns:m="{m}"><m:r><m:t>E = m</m:t></m:r><m:sSup><m:e><m:r><m:t>c</m:t></m:r></m:e><m:sup><m:r><m:t>2</m:t></m:r></m:sup></m:sSup></m:oMath>'))
    if matrix:
        p=d.add_paragraph('Acumulación del flujo ');p._p.append(parse_xml(f'<m:oMath xmlns:m="{m}"><m:nary><m:naryPr><m:chr m:val="∫"/><m:limLoc m:val="subSup"/></m:naryPr><m:sub><m:r><m:t>0</m:t></m:r></m:sub><m:sup><m:r><m:t>1</m:t></m:r></m:sup><m:e><m:r><m:t>x dx</m:t></m:r></m:e></m:nary></m:oMath>'))

