def chart_placeholder(d,kind,index=1):
    p=d.add_paragraph();p._p.append(parse_xml(f'''<w:r xmlns:w="{NS['w']}" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:a="{NS['a']}" xmlns:c="{NS['c']}" xmlns:r="{NS['r']}"><w:drawing><wp:inline><wp:extent cx="5486400" cy="2743200"/><wp:docPr id="{100+index}" name="Gráfico {kind}" descr="Comparación de escenarios"/><a:graphic><a:graphicData uri="{NS['c']}"><c:chart r:id="rCorpusChart{index}"/></a:graphicData></a:graphic></wp:inline></w:drawing></w:r>'''))

def chart_xml(kind):
    ns=NS['c']; root=E.Element('{'+ns+'}chartSpace',nsmap={'c':ns,'a':NS['a'],'r':NS['r']})
    def c(parent,name,val=None):
        n=E.SubElement(parent,'{'+ns+'}'+name)
        if val is not None:n.set('val',str(val))
        return n
    chart=c(root,'chart');plot=c(chart,'plotArea');c(plot,'layout');group=c(plot,kind+'Chart')
    if kind=='bar':c(group,'barDir','col');c(group,'grouping','clustered')
    if kind=='line':c(group,'grouping','standard')
    if kind=='radar':c(group,'radarStyle','marker')
    if kind=='scatter':c(group,'scatterStyle','lineMarker')
    ser=c(group,'ser');c(ser,'idx',0);c(ser,'order',0);tx=c(ser,'tx');c(tx,'v').text='Escenario Aurora'
    cats=['Barrio Norte','Centro','Ribera','Sur'];values=[24,38,31,45]
    for name,nums,vals in ([('xVal',True,[1,2,3,4]),('yVal',True,values)] if kind=='scatter' else [('cat',False,cats),('val',True,values)]):
        node=c(ser,name);ref=c(node,'numRef' if nums else 'strRef');c(ref,'f').text="'Datos'!$B$2:$B$5" if nums else "'Datos'!$A$2:$A$5"
        cache=c(ref,'numCache' if nums else 'strCache')
        if nums:c(cache,'formatCode').text='General'
        c(cache,'ptCount',len(vals))
        for j,value in enumerate(vals):pt=c(cache,'pt');pt.set('idx',str(j));c(pt,'v').text=str(value)
    if kind=='pie':c(group,'firstSliceAng',0)
    else:
        for id in [10001,10002]:c(group,'axId',id)
        for index,id in enumerate([10001,10002]):
            axis=c(plot,'valAx' if kind=='scatter' or index else 'catAx');c(axis,'axId',id);sc=c(axis,'scaling');c(sc,'orientation','minMax');c(axis,'delete',0);c(axis,'axPos','b' if index==0 else 'l');c(axis,'crossAx',10002 if index==0 else 10001);c(axis,'crosses','autoZero')
    legend=c(chart,'legend');c(legend,'legendPos','b');c(chart,'plotVisOnly',1)
    ext=c(root,'externalData');ext.set('{'+NS['r']+'}id','rWorkbook');c(ext,'autoUpdate',0)
    return E.tostring(root,xml_declaration=True,encoding='UTF-8',standalone=True)

def package_patch(path,features):
    with zipfile.ZipFile(path) as z:parts={n:z.read(n) for n in z.namelist()}
    rel=E.fromstring(parts['word/_rels/document.xml.rels']);ct=E.fromstring(parts['[Content_Types].xml']);R='http://schemas.openxmlformats.org/package/2006/relationships';C='http://schemas.openxmlformats.org/package/2006/content-types'
    def relationship(id,type,target):E.SubElement(rel,'{'+R+'}Relationship',Id=id,Type=NS['r']+'/'+type,Target=target)
    def content(path,type):E.SubElement(ct,'{'+C+'}Override',PartName='/'+path,ContentType=type)
    if 'notas' in features:
        for kind in ['footnote','endnote']:
            parts[f'word/{kind}s.xml']=f'''<?xml version="1.0" encoding="UTF-8"?><w:{kind}s xmlns:w="{NS['w']}"><w:{kind} w:type="separator" w:id="-1"><w:p><w:r><w:separator/></w:r></w:p></w:{kind}><w:{kind} w:type="continuationSeparator" w:id="0"><w:p><w:r><w:continuationSeparator/></w:r></w:p></w:{kind}><w:{kind} w:id="2"><w:p><w:r><w:t>{'Nota al pie sobre la interpretación del archivo.' if kind=='footnote' else 'Nota final sobre la procedencia de las fuentes.'}</w:t></w:r></w:p></w:{kind}></w:{kind}s>'''.encode()
            relationship('rCorpus'+kind,kind+'s',kind+'s.xml');content('word/'+kind+'s.xml','application/vnd.openxmlformats-officedocument.wordprocessingml.'+kind+'s+xml')
    chart_kinds=[f.split(':')[1] for f in features if f.startswith('chart:')]
    for j,kind in enumerate(chart_kinds,1):
        parts[f'word/charts/chart{j}.xml']=chart_xml(kind);relationship(f'rCorpusChart{j}','chart',f'charts/chart{j}.xml');content(f'word/charts/chart{j}.xml','application/vnd.openxmlformats-officedocument.drawingml.chart+xml')
        wb=Workbook();ws=wb.active;ws.title='Datos';ws.append(['Barrio','Escenario Aurora'])
        for row in [('Barrio Norte',24),('Centro',38),('Ribera',31),('Sur',45)]:ws.append(row)
        stream=BytesIO();wb.save(stream);parts[f'word/embeddings/datos{j}.xlsx']=stream.getvalue();content(f'word/embeddings/datos{j}.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
        parts[f'word/charts/_rels/chart{j}.xml.rels']=f'<Relationships xmlns="{R}"><Relationship Id="rWorkbook" Type="{NS["r"]}/package" Target="../embeddings/datos{j}.xlsx"/></Relationships>'.encode()
    if 'indice_bibliografia' in features:
        B='http://schemas.openxmlformats.org/officeDocument/2006/bibliography';sources=E.fromstring(parts['customXml/item1.xml']);source=E.SubElement(sources,'{'+B+'}Source')
        for tag,value in [('Tag','Aurora2026'),('SourceType','Book'),('Title','Catálogo de percepción'),('Year','2026'),('City','Ciudad Aurora'),('Publisher','Laboratorio Aurora')]:E.SubElement(source,'{'+B+'}'+tag).text=value
        author=E.SubElement(source,'{'+B+'}Author');author=E.SubElement(author,'{'+B+'}Author');E.SubElement(author,'{'+B+'}Corporate').text='Laboratorio Aurora'
        parts['customXml/item1.xml']=E.tostring(sources,xml_declaration=True,encoding='UTF-8')
    if 'adjunto' in features:
        parts['customXml/adjunto.xml']=b'<archivo xmlns="urn:arles:corpus"><nota>Material adicional del expediente</nota></archivo>'
        content('customXml/adjunto.xml','application/xml');relationship('rCorpusAdjunto','customXml','../customXml/adjunto.xml')
    parts['word/_rels/document.xml.rels']=E.tostring(rel,xml_declaration=True,encoding='UTF-8');parts['[Content_Types].xml']=E.tostring(ct,xml_declaration=True,encoding='UTF-8')
    with zipfile.ZipFile(path,'w',zipfile.ZIP_DEFLATED) as z:
        for n,data in parts.items():z.writestr(n,data)

