def main():
    import argparse
    parser=argparse.ArgumentParser();parser.add_argument('--ids');args=parser.parse_args();selected=set(map(int,args.ids.split(','))) if args.ids else None
    ORIGINALS.mkdir(parents=True,exist_ok=True);image_assets();manifest=json.loads((ROOT/'manifest.json').read_text(encoding='utf-8')) if selected else []
    for i,(title,feature) in enumerate(TOPICS,1):
        if selected and i not in selected:continue
        manifest=[m for m in manifest if m['id']!=i]
        d=base(i,title);features=body(i,d);features.append('ilustracion_editable');path=ORIGINALS/f'{i:02d}.docx';d.save(path);package_patch(path,features)
        with zipfile.ZipFile(path) as z:
            xml=E.fromstring(z.read('word/document.xml'))
            paras=[''.join(p.itertext()) for p in []] # Expected text from source OOXML, not the platform.
            for p in xml.findall('.//w:p',NS):
                text=''.join(p.xpath('.//w:t/text()',namespaces=NS))
                if text.strip():paras.append(text)
            image_parts=[n for n in z.namelist() if n.startswith('word/media/')]
            part_hashes={n:hashlib.sha256(z.read(n)).hexdigest() for n in z.namelist() if not n.endswith('/')}
        manifest.append({'id':i,'filename':path.name,'title':title,'stage':(i-1)//10+1,'features':features,'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'paragraphs':paras,'media':image_parts,'parts':part_hashes})
        print(f'CREATED {i:02d} {title}',flush=True)
    manifest.sort(key=lambda m:m['id'])
    (ROOT/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
    (ROOT/'LEEME.txt').write_text('50 DOCX independientes y progresivos\n\nLos temas y datos de esta colección son ejemplos ficticios para probar lectura, edición y conservación. No corresponden a registros reales de Arles ni a investigaciones realizadas.\nLos originales se conservan en originales. Las pruebas guardan salidas aparte. El manifiesto registra SHA-256, partes OOXML, texto y funciones de cada archivo.\n\n'+ '\n'.join(f'{m["id"]:02d}  {m["title"]}  [{", ".join(m["features"])}]' for m in manifest),encoding='utf-8')

if __name__=='__main__':main()
